let syncConfig={enabled:false,autoSync:true,username:'',folder:'GxTodo',configured:false},syncStatus='尚未设置坚果云同步',syncBusy=false;
const undoQueue=new UndoQueue({duration:()=>db.settings.undoMs});
const undoHost=document.createElement('div');undoHost.id='undo-stack';undoHost.setAttribute('aria-label','可撤销的操作');document.body.append(undoHost);
function renderUndo(){const items=undoQueue.prune(),ids=new Set(items.map(x=>x.id));undoHost.querySelectorAll('.undo-notice').forEach(el=>{if(!ids.has(el.dataset.undoId))el.remove();});for(const item of items){let el=undoHost.querySelector('[data-undo-id="'+item.id+'"]');if(!el){el=document.createElement('div');el.className='undo-notice';el.dataset.undoId=item.id;el.setAttribute('role','status');el.innerHTML='<span>'+h(item.label)+'</span><button data-undo="'+item.id+'" aria-label="撤销'+h(item.label)+'">撤销 <small></small></button>';undoHost.append(el);}const text=Math.ceil((item.expires-Date.now())/1000)+' 秒';if(el.querySelector('small').textContent!==text)el.querySelector('small').textContent=text;}}
function scheduleSync(delay=15000){clearTimeout(syncTimer);if(appForeground&&!document.hidden&&(!window.GxNative?.isForeground||window.GxNative.isForeground())&&navigator.onLine!==false&&syncConfig.enabled&&syncConfig.autoSync)syncTimer=setTimeout(()=>runSync(false),delay); }
function syncVisibility(visible){appForeground=visible;clearTimeout(syncTimer);if(visible)scheduleSync(2000);}
document.addEventListener('visibilitychange',()=>syncVisibility(!document.hidden));
document.addEventListener('gx-app-background',()=>syncVisibility(false));
document.addEventListener('gx-app-foreground',()=>syncVisibility(true));
window.addEventListener('online',()=>scheduleSync(2000));
window.addEventListener('offline',()=>clearTimeout(syncTimer));
function refreshEditor(){if(!ui.editor||ui.dirty)return;const task=findTask(db.tasks,ui.editor.id);if(task){ui.editor=structuredClone(task);ui.editorBase=structuredClone(task);ui.editorVector=currentVector();}else ui.editor.deleted=true;}
undoHost.addEventListener('click',async event=>{const button=event.target.closest('[data-undo]');if(!button)return;const id=button.dataset.undo;let available=false;const saved=await commit(next=>{const restored=undoQueue.apply(id,next);if(restored){available=true;Object.assign(next,restored);}},false);if(saved&&available){undoQueue.remove(id);captureDraft();if(ui.editor){const task=findTask(db.tasks,ui.editor.id);if(task){if(ui.editor.deleted||!ui.dirty){ui.editor=structuredClone(task);ui.editorBase=structuredClone(task);ui.dirty=false;} else{ui.editor.done=task.done;ui.editor.completedAt=task.completedAt;ui.editor.quadrant=task.quadrant;ui.editor.order=task.order;}}}render();renderUndo();toast('已撤销，之后的其他修改已保留');}else if(!available)toast('反悔时间已结束');});
setInterval(()=>{if(undoQueue.items.length)renderUndo();},250);
async function runSync(manual=true){
 if(switching||(!manual&&(!appForeground||document.hidden||navigator.onLine===false)))return;if(syncBusy){if(manual)toast('正在同步');return;}if(!syncConfig.enabled){if(manual)openModal({type:'sync'});return;}
 captureDraft();if(ui.dirty||ui.confirmation){if(manual)toast('请先保存或关闭正在编辑的详情，再同步');scheduleSync(20000);return;}
 if(undoQueue.prune().length){if(manual){toast('反悔时间结束后自动同步');setTimeout(()=>runSync(true),Math.max(...undoQueue.items.map(x=>x.expires))-Date.now()+300);}else scheduleSync(Math.max(...undoQueue.items.map(x=>x.expires))-Date.now()+300);return;}
 syncBusy=true;syncStatus='正在与坚果云同步…';updateSyncStatus();let succeeded=false;
 let more=false;try{await commitQueue;const result=await exchange(db,{shouldContinue:()=>appForeground&&!document.hidden&&navigator.onLine!==false});more=result.more;syncConflicts=result.conflicts;const refresh=commitQueue.then(async()=>{db=await readState();refreshEditor();});commitQueue=refresh.catch(()=>{});await refresh;syncStatus=(more?'本轮变化已保存，正在分批继续同步':'已补齐本次检查到的全部变化')+' · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+(syncConflicts.length?' · '+syncConflicts.length+' 处冲突待处理':'');succeeded=true;syncFailures=0;if(!ui.dirty&&!ui.modal)render();if(manual||syncConflicts.length)toast(syncStatus);}
 catch(error){syncStatus=error.message;syncFailures++;if(manual)toast(syncStatus);}finally{syncBusy=false;updateSyncStatus();scheduleSync(succeeded?(more?10000:300000+Math.random()*30000):Math.min(1800000,60000*2**Math.min(syncFailures,5))+Math.random()*10000);}
}
function updateSyncStatus(){const status=$('#sync-status');if(status)status.textContent=syncStatus;const button=$('[data-action="sync-now"]');if(button)button.disabled=syncBusy;}
function syncModal(){return '<h2>坚果云同步 · '+h(currentAccount().name)+'<button data-action="close-modal" aria-label="关闭同步设置">×</button></h2><form id="sync-form"><label class="setting-switch"><span>启用坚果云同步</span><input type="checkbox" name="enabled" '+(syncConfig.enabled?'checked':'')+'></label><label>坚果云账号<input name="username" autocomplete="username" value="'+h(syncConfig.username)+'" placeholder="注册邮箱"></label><label>第三方应用密码<input type="password" name="password" autocomplete="new-password" placeholder="'+(syncConfig.configured?'已保存，留空保持原密码':'在坚果云账户安全中添加应用密码')+'"></label><label>同步目录<input name="folder" value="'+h(syncConfig.folder)+'" pattern="[A-Za-z0-9_-]{1,60}" required></label><label class="setting-switch"><span>打开应用时自动同步<small>仅在前台约每 5 分钟检查；编辑后合并上传，离线或后台暂停</small></span><input type="checkbox" name="autoSync" '+(syncConfig.autoSync?'checked':'')+'></label><p class="help">同一数据账号的网页和手机填写相同坚果云账号及目录；不同数据账号请使用不同目录。服务地址：https://dav.jianguoyun.com/dav/ 。应用密码只保存在这台设备，不会进入备份或云端任务文件。</p><p class="help">每台设备独立记录同步进度；同一字段的并发版本会保留，可选择要采用的内容。同步包含任务、子任务、便签、项目、标签、地点；交互设置单独保留。</p><button type="button" class="sync-settings-link" data-action="sync-conflicts">查看并处理同步冲突 →</button><p id="sync-status" role="status">'+h(syncStatus)+'</p><footer><button type="button" class="secondary" data-action="sync-now" '+(syncBusy?'disabled':'')+'>立即同步</button><button type="submit" class="primary">保存同步设置</button></footer></form>';}

const ui={focusQuadrant:null,navOpen:false,filtersOpen:false,page:'task',date:dayKey(),period:'day',status:'pending',completedOn:null,mode:'quadrants',listLimits:{},group:null,query:'',archive:false,editor:null,dirty:false,draftVersion:0,picker:null,pickerQuery:'',pickerEdited:false,calendarMonth:'',modal:null,timeline:null,timelineStatus:'all',saving:false};

