function accountsModal(){return '<h2>账号管理<button data-action="close-modal" aria-label="关闭账号管理">×</button></h2><p class="help">每个账号独立保存任务、便签、分类和同步设置。</p><div class="account-list">'+registry.accounts.map(a=>'<button class="account-option '+(a.id===accountId()?'is-current':'')+'" data-action="switch-account" data-id="'+h(a.id)+'" '+(a.id===accountId()?'disabled':'')+'><span class="account-avatar">'+h(a.name.slice(-1))+'</span><span><strong>'+h(a.name)+'</strong><small>'+(a.id===accountId()?'当前使用':'点击切换')+'</small></span>'+(a.id===accountId()?'<span aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div><form id="account-rename-form"><label>当前账号名称<input name="name" aria-label="当前账号名称" value="'+h(currentAccount().name)+'" required maxlength="32"></label><button class="secondary" type="submit">保存名称</button></form><form id="account-create-form"><h3>添加账号</h3><label>账号名称<input name="name" aria-label="新账号名称" placeholder="例如：工作" required maxlength="32"></label><label>独立同步目录<input name="folder" aria-label="新账号同步目录" placeholder="留空自动生成" pattern="[A-Za-z0-9_-]{1,60}"></label><button type="submit" class="primary">创建空白账号</button></form><p class="help">在每个账号的“设置 → 坚果云同步”中单独配置。默认账号 A 使用 GxTodo，账号 B 使用 GxTodo-B。手机和网页分别创建对应账号并填写相同目录即可同步。</p>';}
async function switchAccount(id){
 if(id===accountId()||switching||accountBusy)return;
 if(syncBusy){toast('请等待本次同步完成后再切换账号');return;}
 switching=true;clearTimeout(syncTimer);app.inert=true;
 try{
  if(!await canLeaveEditor())return;
  const note=$('#new-note')?.value.trim();if(note&&!await commit(next=>next.notes.unshift({id:uid(),body:note,createdAt:new Date().toISOString()})))return;
  await commitQueue;await accountCall({op:'activate',id});reminders?.dispose();history.replaceState(null,'','#/task');location.reload();
 }catch(error){toast('未切换：'+error.message);}finally{switching=false;app.inert=false;scheduleSync();}
}
async function addQuickSubtask(focus=true){
 if(quickAdding)return false;captureDraft();const title=ui.quickTitle?.trim();if(!title){if(focus)$('#quick-subtask')?.focus();return true;}
 const parentId=ui.editor?.id;if(!parentId)return false;const createdAt=new Date().toISOString();quickAdding=true;
 try{
  if(!await saveTask())return false;
  const saved=await commit(next=>{const parent=findTask(next.tasks,parentId);if(!parent)throw new Error('父任务已删除');parent.subtasks.push(quickSubtask(parent,title,uid(),createdAt));},'子任务已添加');
  if(saved&&ui.editor?.id===parentId){ui.quickTitle='';refreshEditor();}return saved;
 }finally{quickAdding=false;render();if(focus)$('#quick-subtask')?.focus();}
}

function conflictsModal(){return '<h2>同步冲突<button data-action="close-modal" aria-label="关闭同步冲突">×</button></h2><p class="help">不同设备同时修改了同一字段。所有版本均已保留；选择后会同步到其他设备。</p>'+(syncConflicts.length?syncConflicts.map((c,i)=>'<section class="sync-conflict"><strong>'+h(c.title)+'</strong><p>'+h(({title:'任务标题',notes:'备注',body:'便签',_deleted:'是否删除',done:'完成状态',start:'开始时间',end:'结束时间',parentId:'父任务',order:'显示顺序',createdAt:'创建时间',completedAt:'完成时间',reminderAt:'提醒时间',seriesId:'重复任务系列',generatedFrom:'重复来源',name:'名称',description:'描述',archived:'归档状态',allDay:'全天任务',repeat:'重复规则',reminder:'提醒设置',weight:'分值',review:'完成复盘',project:'项目',place:'地点',tags:'标签'})[c.field]||c.field)+'</p>'+c.values.map((v,j)=>'<button class="secondary" data-action="resolve-sync" data-conflict="'+i+'" data-choice="'+j+'">采用：'+h(conflictValue(c.field,v.value))+'</button>').join('')+'</section>').join(''):'<p>当前没有待处理的冲突。</p>');}

function listPageKey(key){return JSON.stringify([key,ui.page,ui.date,ui.period,ui.status,ui.timeline,ui.timelineStatus,ui.query,ui.group]);}
function listLimit(key){return ui.listLimits[key]||100;}
function moreRows(key,total){return total>listLimit(key)?'<button class="load-more secondary" data-action="load-more" data-key="'+h(key)+'">继续加载（剩余 '+(total-listLimit(key))+' 项）</button>':'';}
function pagedRows(items,name,renderRow){const key=listPageKey(name);return items.slice(0,listLimit(key)).map(renderRow).join('')+moreRows(key,items.length);}

function conflictValue(field,value){if(field==='_deleted')return value?'删除':'保留';if(field==='parentId')return value?(findTask(db.tasks,value)?.title||'父任务已删除'):'顶层任务';if(field==='repeat')return value?repeatLabel(value):'不重复';if(field==='reminder')return value?(value.mode==='relative'?'提前 '+(value.minutes||0)+' 分钟提醒':value.at||'按已保存时间提醒'):'不提醒';if(Array.isArray(value))return value.join('、')||'无';if(typeof value==='boolean')return value?'是':'否';if(value==null||value==='')return '无';return typeof value==='object'?JSON.stringify(value):String(value);}
